def is_majority(arr, n, x):
    if n == 0:
        return False

    def lower_bound():
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound():
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower_bound()
    last = upper_bound()

    return (last - first) * 2 > n


if __name__ == "__main__":
    assert is_majority([1, 2, 3, 3, 3, 3, 10], 7, 3) == True
