def minPath(grid, k):
    n = len(grid)
    x = y = -1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                x, y = i, j
                break
        if x != -1:
            break

    second = None
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
