class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def all_substrings(x: str):
            res = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    res.append(x[i:j])
            return res

        sub_s = all_substrings(s)
        sub_t = all_substrings(t)

        max_possible = len(s) + len(t)
        ans = 0

        for a in sub_s:
            for b in sub_t:
                if len(a) + len(b) <= ans:
                    continue
                cand = a + b
                if cand == cand[::-1]:
                    ans = len(cand)
                    if ans == max_possible:
                        return ans

        return ans
