            seg[i] = max(seg[i << 1], seg[(i << 1) | 1])

        def find_first(x: int) -> int:
            idx = 1
            while idx < size:
                left = idx << 1
                if seg[left] >= x:
                    idx = left
                else:
                    idx = left | 1
            return idx - size

        unplaced = 0

        for x in fruits:
            if seg[1] < x:
                unplaced += 1
                continue

            pos = find_first(x)

            idx = size + pos
            seg[idx] = 0
            idx >>= 1
            while idx:
                seg[idx] = max(seg[idx << 1], seg[(idx << 1) | 1])
                idx >>= 1

        return unplaced
