from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # At the same timestamp, OFFLINE events are processed before MESSAGE events.
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        offline_until = [0] * numberOfUsers
        mentions = [0] * numberOfUsers

        for event in events:
            timestamp = int(event[1])

            if event[0] == "OFFLINE":
                user_id = int(event[2])
                offline_until[user_id] = timestamp + 60
            else:  # MESSAGE
                for token in event[2].split():
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if offline_until[i] <= timestamp:
                                mentions[i] += 1
                    else:
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions
